:root {
  color-scheme: dark;
  --br-bg-deep: #050912;
  --br-bg-panel: rgba(15, 23, 42, 0.88);
  --br-gold: #f59e0b;
  --br-gold-bright: #fde047;
  --br-cyan: #38bdf8;
  --br-emerald: #22c55e;
  --br-crimson: #ef4444;
  --br-text-main: #f8fafc;
  --br-text-muted: #94a3b8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  background: var(--br-bg-deep);
  color: var(--br-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang SC",
    "Microsoft YaHei", sans-serif;
  overflow-x: hidden;
  user-select: none;
}

.br-app {
  position: relative;
  width: 100%;
  max-width: 100vw;
  box-sizing: border-box;
  height: 100vh;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 8px 16px 10px;
  gap: 8px;
  background:
    radial-gradient(
      circle at 50% 42%,
      rgba(19, 32, 54, 0.94) 0%,
      rgba(8, 13, 25, 0.98) 66%,
      #04070d 100%
    );
  overflow: hidden;
}

/* Top Bar */
.br-topbar {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: nowrap;
  padding: 6px 14px;
  border-radius: 12px;
  background: linear-gradient(
    180deg,
    rgba(15, 23, 42, 0.92) 0%,
    rgba(8, 13, 24, 0.95) 100%
  );
  border: 1px solid rgba(245, 158, 11, 0.28);
  box-shadow:
    0 8px 24px rgba(0, 0, 0, 0.48),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(14px);
  flex-shrink: 0;
  max-width: 1060px;
  width: 100%;
  margin: 0 auto;
}

.br-brand {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.br-emblem {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  filter: drop-shadow(0 2px 6px rgba(245, 158, 11, 0.3));
}

.br-brand h1 {
  font-size: 15.5px;
  font-weight: 800;
  letter-spacing: 0.02em;
  background: linear-gradient(135deg, #fef08a 0%, #f59e0b 65%, #fbbf24 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  white-space: nowrap;
  flex-shrink: 0;
}

.br-status-pills {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: 6px;
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
  min-width: 0;
}

.br-status-pills::-webkit-scrollbar {
  display: none;
}

.br-phase-pill,
.br-alive-pill,
.br-storm-pill,
.br-turn-pill,
.br-winner-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  padding: 2.5px 8.5px;
  border-radius: 999px;
  white-space: nowrap;
  flex-shrink: 0;
}

.br-phase-pill {
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.42);
  color: #fde047;
}

.br-alive-pill {
  background: rgba(34, 197, 94, 0.14);
  border: 1px solid rgba(34, 197, 94, 0.38);
  color: #86efac;
}

.br-storm-pill {
  background: rgba(56, 189, 248, 0.14);
  border: 1px solid rgba(56, 189, 248, 0.38);
  color: #7dd3fc;
}

.br-turn-pill {
  background: rgba(168, 85, 247, 0.18);
  border: 1px solid rgba(168, 85, 247, 0.45);
  color: #d8b4fe;
}

.br-winner-pill {
  background: rgba(245, 158, 11, 0.25);
  border: 1px solid #fde047;
  color: #fde047;
  box-shadow: 0 0 12px rgba(245, 158, 11, 0.35);
}

.br-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: nowrap;
  flex-shrink: 0;
}

.br-top-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 29px;
  padding: 0 10px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: rgba(30, 41, 59, 0.78);
  color: #e2e8f0;
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.br-top-btn:hover:not(:disabled) {
  border-color: rgba(245, 158, 11, 0.55);
  background: rgba(51, 65, 85, 0.88);
}

.br-top-btn.is-icon {
  padding: 0 7.5px;
}

.br-top-btn.is-active {
  background: rgba(245, 158, 11, 0.22);
  border-color: rgba(251, 191, 36, 0.65);
  color: #fde047;
}

.br-top-btn.is-primary {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border-color: #fde047;
  color: #fffbeb;
  box-shadow: 0 2px 10px rgba(245, 158, 11, 0.32);
}

.br-error-toast {
  position: absolute;
  top: 54px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 8px;
  background: rgba(127, 29, 29, 0.96);
  border: 1px solid #f87171;
  color: #fef2f2;
  font-size: 12px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.65);
}

.br-error-toast button {
  background: transparent;
  border: none;
  color: #fecaca;
  cursor: pointer;
  display: flex;
}

/* Main Arena */
.br-arena {
  position: relative;
  z-index: 5;
  flex: 1;
  display: grid;
  grid-template-columns: 184px minmax(0, 1fr) 184px;
  gap: 14px;
  align-items: stretch;
  min-height: 0;
  max-width: 1060px;
  width: 100%;
  margin: 0 auto;
}

.br-wing {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  height: 100%;
  min-width: 0;
}

/* Operative Card */
.br-agent-card {
  position: relative;
  height: 104px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 8px 10px;
  border-radius: 12px;
  background: linear-gradient(
    165deg,
    rgba(25, 36, 56, 0.94) 0%,
    rgba(12, 18, 33, 0.98) 100%
  );
  border: 1px solid rgba(148, 163, 184, 0.22);
  box-shadow:
    0 6px 16px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.br-agent-card.is-turn {
  border-color: #fbbf24;
  transform: translateY(-1px);
}

.br-agent-card.is-winner {
  border-color: #fde047;
  box-shadow: 0 0 22px rgba(250, 204, 21, 0.42);
}

.br-agent-card.is-eliminated {
  opacity: 0.46;
  filter: saturate(0.28);
}

.br-agent-top {
  display: flex;
  align-items: center;
  gap: 8px;
}

.br-avatar-wrap {
  position: relative;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1.5px solid #38bdf8;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.br-avatar-wrap.is-token {
